var kw = Tama.Args.Get(args, "keyword", "canopy").ToLower();
Func<XYZ,double[]> M = p => new[]{Math.Round(p.X*0.3048,4),Math.Round(p.Y*0.3048,4),Math.Round(p.Z*0.3048,4)};
var res = new List<object>();
foreach (var fi in new FilteredElementCollector(doc).OfClass(typeof(FamilyInstance)).Cast<FamilyInstance>())
{
    var fam = fi.Symbol.Family.Name; var typ = fi.Symbol.Name;
    if (!(fam.ToLower().Contains(kw) || typ.ToLower().Contains(kw))) continue;
    var lp = fi.Location as LocationPoint; var bb = fi.get_BoundingBox(null);
    var lvl = doc.GetElement(fi.LevelId) as Level; var t = fi.GetTransform();
    res.Add(new { id = fi.Id.IntegerValue, family = fam, type = typ, category = fi.Category?.Name,
        level = lvl?.Name, levelElev_m = lvl == null ? (double?)null : Math.Round(lvl.Elevation*0.3048,4),
        point_m = lp == null ? null : M(lp.Point), rotation_deg = lp == null ? 0 : Math.Round(lp.Rotation*180/Math.PI,4),
        mirrored = fi.Mirrored, basisX = new[]{Math.Round(t.BasisX.X,6),Math.Round(t.BasisX.Y,6),Math.Round(t.BasisX.Z,6)},
        offset_m = Math.Round((fi.get_Parameter(BuiltInParameter.INSTANCE_FREE_HOST_OFFSET_PARAM)?.AsDouble() ?? 0)*0.3048,4),
        bbMin_m = bb==null?null:M(bb.Min), bbMax_m = bb==null?null:M(bb.Max), host = fi.Host?.Name });
}
var fams = new FilteredElementCollector(doc).OfClass(typeof(Family)).Cast<Family>().Where(f=>f.Name.ToLower().Contains(kw)).Select(f=>new{id=f.Id.IntegerValue,f.Name, cat=f.FamilyCategory?.Name, inPlace=f.IsInPlace}).ToList();
var ds = new FilteredElementCollector(doc).OfClass(typeof(DirectShape)).Cast<DirectShape>().Select(d=>new{id=d.Id.IntegerValue,name=d.Name,cat=d.Category?.Name}).Take(20).ToList();
var imps = new FilteredElementCollector(doc).OfClass(typeof(ImportInstance)).Cast<ImportInstance>().Select(i=>new{id=i.Id.IntegerValue,name=(doc.GetElement(i.GetTypeId()) as ElementType)?.Name}).ToList();
var lvls = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().OrderBy(l=>l.Elevation).Select(l=>new{l.Name,elev_m=Math.Round(l.Elevation*0.3048,4)}).ToList();
return new { instances = res, families = fams, directShapes = ds, imports = imps, levels = lvls, doc = doc.Title, isFamily = doc.IsFamilyDocument };
